CREATE FUNCTION public.spendshift_increment_metrics_v2(p_event text,p_page text DEFAULT NULL,p_source text DEFAULT NULL,p_campaign text DEFAULT NULL,p_device text DEFAULT NULL,p_browser text DEFAULT NULL,p_placement text DEFAULT NULL,p_question integer DEFAULT NULL,p_faq text DEFAULT NULL,p_error text DEFAULT NULL,p_choice text DEFAULT NULL,p_lcp text DEFAULT NULL,p_inp text DEFAULT NULL,p_cls text DEFAULT NULL,p_duration text DEFAULT NULL,p_market text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
BEGIN
 -- Server-only market marginal is required on arrivals; no location on other events.
 IF (p_event='site_entry' AND (p_market IS NULL OR p_market NOT IN ('australia','outside_australia','unknown'))) OR (p_event IS DISTINCT FROM 'site_entry' AND p_market IS NOT NULL) THEN RAISE EXCEPTION 'invalid_metric'; END IF;
 IF p_event IS NULL OR NOT ((p_event='site_entry' AND p_page IS NOT NULL AND p_source IS NOT NULL AND p_campaign IS NOT NULL AND p_device IS NOT NULL AND p_browser IS NOT NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='public_page_view' AND p_page IS NOT NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='engaged_10s' AND p_page IS NOT NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='engaged_30s' AND p_page IS NOT NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='scroll_25' AND p_page IS NOT NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='scroll_50' AND p_page IS NOT NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='scroll_75' AND p_page IS NOT NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='scroll_90' AND p_page IS NOT NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='public_cta_click' AND p_page IS NOT NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NOT NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='public_nav_click' AND p_page IS NOT NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='faq_open' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NOT NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='lcp_bucket' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NOT NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='inp_bucket' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NOT NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='cls_bucket' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NOT NULL AND p_duration IS NULL) OR (p_event='safe_ui_error' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NOT NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='privacy_notice_shown' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='optional_choice' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NOT NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event IN ('home_engaged_60s','home_engaged_120s','home_section_hero_seen','home_section_benefits_seen','home_section_offer_seen','home_section_example_seen','home_section_faq_seen','home_section_final_seen','home_cta_header_impression','home_cta_header_click','home_cta_hero_impression','home_cta_hero_click','home_cta_offer_impression','home_cta_offer_click','home_cta_final_impression','home_cta_final_click','home_cta_footer_impression','home_cta_footer_click') AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='audit_arrival' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='audit_start' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='audit_question_seen' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NOT NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='audit_question_advanced' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NOT NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='audit_back' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NOT NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='audit_reset' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='audit_complete' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='audit_duration_bucket' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NOT NULL) OR (p_event='results_view' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='upgrade_offer_view' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='upgrade_cta_click' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='checkout_opened' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='personalisation_view' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL) OR (p_event='personalisation_step_advanced' AND p_page IS NULL AND p_source IS NULL AND p_campaign IS NULL AND p_device IS NULL AND p_browser IS NULL AND p_placement IS NULL AND p_question IS NULL AND p_faq IS NULL AND p_error IS NULL AND p_choice IS NULL AND p_lcp IS NULL AND p_inp IS NULL AND p_cls IS NULL AND p_duration IS NULL)) THEN RAISE EXCEPTION 'invalid_metric'; END IF;
 SELECT (now() AT TIME ZONE 'Australia/Sydney')::date,p_event,d,b,1 FROM (VALUES ('all','all'),('page',p_page),('source',p_source),('campaign',p_campaign),('device',p_device),('browser',p_browser),('placement',p_placement),('question',p_question::text),('faq',p_faq),('error',p_error),('choice',p_choice),('lcp',p_lcp),('inp',p_inp),('cls',p_cls),('duration',p_duration),('market',p_market)) AS cells(d,b) WHERE b IS NOT NULL ORDER BY d,b
 ON CONFLICT(metric_date,metric_code,dimension_code,bucket_code) DO UPDATE SET event_count=spendshift_metrics_v2_daily.event_count+1;
END $$;
