CREATE FUNCTION public.spendshift_prune_metrics_v2() RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=pg_catalog,public AS $$ DELETE FROM public.spendshift_metrics_v2_daily WHERE metric_date <= (now() AT TIME ZONE 'Australia/Sydney')::date - 180; $$;
